using System.IO.Compression;
using System.Net;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using GameTranslator.Core;
namespace GameTranslator.Translation.Tests;
public class ArabicGamePackTests
{
    [Fact]public async Task VerifiedArabicMemoryBypassesBothEnginesAndKeepsSpeaker(){var dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString("N"));try{var handler=new Service();var store=new ArabicGamePackStore(dir,new HttpClient(handler));await store.EnsureAsync();Assert.Equal(1,store.Entries);Assert.Equal("جيسون: أوشكنا على الوصول.",store.Find("GTA6","Jason: Almost there!"));Assert.Equal("جيسون: أوشكنا على الوصول.\nلوسيا: أوشكنا على الوصول.",store.Find("GTA6","Jason: Almost\nthere!\nLucia: Almost\nthere!"));Assert.Null(store.Find("RDR2","Almost there!"));Assert.Null(store.Find("GTA6","Almost home!"));await store.EnsureAsync();Assert.Equal(2,handler.Calls);store.Enabled=false;Assert.Null(store.Find("GTA6","Almost there!"));}finally{Directory.Delete(dir,true);}}
    [Fact]public async Task WrongChecksumNeverReplacesVerifiedLocalPack(){var dir=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString("N"));try{var handler=new Service();var store=new ArabicGamePackStore(dir,new HttpClient(handler));await store.EnsureAsync();handler.BadHash=true;await store.EnsureAsync(force:true);Assert.Equal(1,store.Entries);Assert.Contains("جاهزة",store.Status);Assert.Equal("أوشكنا على الوصول.",store.Find("GTA6","Almost there!"));}finally{Directory.Delete(dir,true);}}
    [Fact]public void LogTailRetriesIncompleteRowsAndOnlyReadsAppendedBytes(){var file=Path.GetTempFileName();try{var tail=new ComparisonLogTail(file);Assert.Empty(tail.ReadNew());var row=new ComparisonEntry(DateTimeOffset.UtcNow,"one","GTA6","QuickMT","Almost there!","أوشكنا على الوصول.",null,new(),false,AreaId:"phone",AreaName:"الجوال");var json=JsonSerializer.Serialize(row);File.WriteAllText(file,json[..20]);Assert.Empty(tail.ReadNew());File.AppendAllText(file,json[20..]+"\n");Assert.Equal("الجوال",Assert.Single(tail.ReadNew()).AreaName);Assert.Empty(tail.ReadNew());}finally{File.Delete(file);}}
    private sealed class Service:HttpMessageHandler{public int Calls;public bool BadHash;private readonly byte[] bytes;public Service(){using var output=new MemoryStream();using(var gzip=new GZipStream(output,CompressionMode.Compress,true)){var json=JsonSerializer.Serialize(new{format=2,id="gta-6-ar",lang="ar",entries=new Dictionary<string,string>{{PackKey.Key("Almost there!")!,"أوشكنا على الوصول."}}});gzip.Write(Encoding.UTF8.GetBytes(json));}bytes=output.ToArray();}protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken token){Calls++;if(r.RequestUri!.AbsolutePath.EndsWith("gta-6-ar"))return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new ByteArrayContent(bytes)});var sha=BadHash?new string('0',64):Convert.ToHexStringLower(SHA256.HashData(bytes));return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(JsonSerializer.Serialize(new{packs=new[]{new{id="gta-6-ar",lang="ar",size=bytes.Length,sha256=sha}}}))});}}
}
